(function(E){ const x = E["exam-01"] = E["exam-01"] || {units:{}}; (x.units = x.units || {})["x01-l2"] = {"id":"x01-l2","patterns":["L2-work"],"title":{"en":"Listening Part 2: a career podcast","tr":"Listening Part 2: kariyer podcast’i","fa":"Listening Part 2: پادکستی درباره‌ی شغل"},"objective":{"en":"In this lesson you will learn to answer multiple choice and matching questions on an interview, when every option is mentioned and only one is confirmed.","tr":"Bu derste her seçeneğin söylendiği ama yalnızca birinin doğrulandığı bir röportajda çoktan seçmeli ve eşleştirme sorularını cevaplamayı öğreneceksin.","fa":"در این درس یاد می‌گیری در یک مصاحبه به سؤال‌های چندگزینه‌ای و جورکردنی جواب بدهی، وقتی از همه‌ی گزینه‌ها حرف زده می‌شود و فقط یکی تأیید می‌شود."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 2: a career podcast","tr":"Listening Part 2: kariyer podcast’i","fa":"Listening Part 2: پادکستی درباره‌ی شغل"},"objective":{"en":"In this lesson you will learn to answer multiple choice and matching questions on an interview, when every option is mentioned and only one is confirmed.","tr":"Bu derste her seçeneğin söylendiği ama yalnızca birinin doğrulandığı bir röportajda çoktan seçmeli ve eşleştirme sorularını cevaplamayı öğreneceksin.","fa":"در این درس یاد می‌گیری در یک مصاحبه به سؤال‌های چندگزینه‌ای و جورکردنی جواب بدهی، وقتی از همه‌ی گزینه‌ها حرف زده می‌شود و فقط یکی تأیید می‌شود."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Options","tr":"Seçenek","fa":"گزینه"},"value":"A-C"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a makeup artist’s career","tr":"Bu sınav: bir makyaj sanatçısının kariyeri","fa":"این آزمون: کار یک گریمور"},"intro":{"en":"Part 2 is one main voice giving everyday information: a tour, a local plan or, as here, a talk about a job. Here a host asks short questions and the guest does most of the talking.","tr":"Part 2 günlük bilgi veren tek bir ana sestir: bir tur, yerel bir plan ya da burada olduğu gibi bir meslek hakkında konuşma. Burada sunucu kısa sorular soruyor, konuşmanın çoğunu konuk yapıyor.","fa":"Part 2 یک صدای اصلی است که اطلاعات روزمره می‌دهد: یک تور، یک طرح محلی یا مثل این‌جا، صحبتی درباره‌ی یک شغل. این‌جا مجری سؤال‌های کوتاه می‌پرسد و بیشترِ حرف‌ها را مهمان می‌زند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x01-l2-ctx","exam":true,"patterns":["L2-work"],"often":{"pattern":"L2-work","n":9,"of":40,"label":{"en":"Comes up often in the real exam: 9 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A podcast about a creative job","tr":"Yaratıcı bir meslek hakkında bir podcast","fa":"پادکستی درباره‌ی یک شغل خلاق"},"asks":{"en":"A host interviews someone about their career: how they started, their training, problems at the start, advice, what they prefer and what comes next. Then the guest says what each everyday task needs.","tr":"Bir sunucu birine kariyerini soruyor: nasıl başladığını, eğitimini, başlangıçtaki zorlukları, tavsiyelerini, neyi tercih ettiğini ve sırada ne olduğunu. Sonra konuk her günlük işin neye ihtiyaç duyduğunu anlatıyor.","fa":"یک مجری با کسی درباره‌ی کارش مصاحبه می‌کند: چطور شروع کرد، چه آموزشی دید، اول کار چه مشکلی داشت، چه توصیه‌ای دارد، چه چیزی را ترجیح می‌دهد و کار بعدی‌اش چیست. بعد مهمان می‌گوید هر کار روزمره به چه چیزی نیاز دارد."},"fields":["How it started","Training","The hardest thing","Advice","Preference and why","Next project","Task → what it needs"],"words":[{"a":"first became interested","b":"what got me into it / it all began when","tr":"ilk ilgisini çeken","fa":"اولین بار علاقه‌مند شد"},{"a":"work placements","b":"time working with real companies","tr":"staj, uygulamalı çalışma","fa":"کارآموزی در محیط واقعی"},{"a":"mainly theory","b":"mostly lectures and reading","tr":"çoğunlukla teori","fa":"بیشتر تئوری"},{"a":"the hardest part","b":"the biggest challenge / what’s really difficult","tr":"en zor kısım","fa":"سخت‌ترین بخش"},{"a":"a paid job","b":"someone pays you / proper work","tr":"ücretli bir iş","fa":"کاری با دستمزد"},{"a":"recommend","b":"my advice would be / I’d always tell people to","tr":"tavsiye etmek","fa":"توصیه کردن"},{"a":"specialise","b":"focus on one area","tr":"uzmanlaşmak","fa":"تخصص گرفتن"},{"a":"creative freedom","b":"I can do it my own way / nobody tells me what to do","tr":"yaratıcı özgürlük","fa":"آزادی خلاقانه"},{"a":"next project","b":"what I’m starting soon / my next job","tr":"sıradaki proje","fa":"پروژه‌ی بعدی"},{"a":"working quickly","b":"you have to be fast / there’s no time","tr":"hızlı çalışmak","fa":"سریع کار کردن"},{"a":"attention to detail","b":"every little thing matters / you look closely","tr":"ayrıntıya dikkat","fa":"دقت به جزئیات"},{"a":"getting on with people","b":"being friendly / building trust","tr":"insanlarla iyi geçinmek","fa":"کنار آمدن با آدم‌ها"}],"traps":[{"en":"Every option is mentioned. \"I did think about teaching, but really it was a summer job that started it.\" The answer comes after but, really or in fact.","tr":"Her seçenekten söz edilir. \"Öğretmenliği düşündüm, ama aslında her şeyi bir yaz işi başlattı.\" Cevap but, really ya da in fact’ten sonra gelir.","fa":"از همه‌ی گزینه‌ها حرف زده می‌شود. «به معلمی هم فکر کردم، اما در واقع یک کار تابستانی همه‌چیز را شروع کرد». جواب بعد از but، really یا in fact می‌آید."},{"en":"People assume X: \"Everyone thinks I do it for the travel... that isn’t really why.\" What other people think is usually a distractor.","tr":"İnsanlar X sanır: \"Herkes bunu seyahat için yaptığımı sanıyor... asıl neden bu değil.\" Başkalarının düşündüğü genelde çeldiricidir.","fa":"مردم خیال می‌کنند X: «همه فکر می‌کنند به‌خاطر سفر این کار را می‌کنم... دلیل اصلی این نیست». چیزی که دیگران فکر می‌کنند معمولاً گزینه‌ی انحرافی است."},{"en":"In the matching task one quality can be mentioned and then dismissed: \"Patience helps, of course, but what really counts there is...\" Wait for what counts.","tr":"Eşleştirmede bir nitelikten söz edilip sonra geçilebilir: \"Sabır elbette yardımcı olur, ama orada asıl önemli olan...\" Asıl önemli olanı bekle.","fa":"در تمرین جورکردن ممکن است از یک ویژگی حرف زده شود و بعد کنار گذاشته شود: «صبر البته کمک می‌کند، اما آن‌جا چیزی که واقعاً مهم است...». منتظر چیزی بمان که واقعاً مهم است."}],"example":{"lines":[["Host","Why did you leave the bank?"],["Guest","Everyone thinks it was the money, but the salary was fine. And I didn’t mind the long hours. I just wanted a job where I could make something with my hands."]],"item":"Why did the guest leave the bank? A the pay  B the hours  C wanting practical work","answer":"C","why":{"en":"Pay and hours are both mentioned and ruled out. \"Make something with my hands\" = practical work.","tr":"Maaş ve saatler söyleniyor ama eleniyor. \"Elleriyle bir şey yapmak\" = pratik iş.","fa":"حقوق و ساعت کار هر دو گفته و رد می‌شوند. «با دست‌هایم چیزی بسازم» یعنی کار عملی."}}},{"id":"L2-work","ctx":["L2-work"],"title":{"en":"Work talks: induction, training and careers","tr":"İş konuşmaları: oryantasyon, eğitim ve kariyer","fa":"صحبت‌های کاری: آشنایی، آموزش و شغل"},"asks":{"en":"A manager welcomes new staff, a trainer explains a job, or someone talks about a career. Questions ask about duties, rules, who is responsible for what, what the job needs and advice for new starters.","tr":"Bir yönetici yeni personeli karşılar, bir eğitmen işi anlatır ya da biri bir kariyerden söz eder. Sorular görevleri, kuralları, kimin neden sorumlu olduğunu, işin ne gerektirdiğini ve yeni başlayanlara tavsiyeleri sorar.","fa":"یک مدیر به کارکنان تازه خوش‌آمد می‌گوید، یک مربی کاری را توضیح می‌دهد، یا کسی درباره‌ی یک شغل حرف می‌زند. سؤال‌ها درباره‌ی وظایف، قانون‌ها، اینکه چه کسی مسئول چیست، شرایط کار و توصیه به تازه‌کارهاست."},"fields":["What should new staff do on the first day?","Who should staff report problems to?","What is the most important quality for this job?","Which TWO things must staff bring?","What is each person responsible for?","What advice does the speaker give?"],"words":[{"a":"induction","b":"your first day / the welcome session","tr":"oryantasyon","fa":"دوره‌ی آشنایی"},{"a":"rota","b":"the timetable of who works when","tr":"vardiya çizelgesi","fa":"جدول شیفت‌ها"},{"a":"report to","b":"the person you go to","tr":"... -e bağlı olmak","fa":"زیر نظر ... بودن"},{"a":"responsible for","b":"in charge of / looks after","tr":"... -den sorumlu","fa":"مسئولِ"},{"a":"health and safety","b":"the rules that stop accidents","tr":"iş sağlığı ve güvenliği","fa":"ایمنی و بهداشت کار"},{"a":"essential","b":"the one thing you must have","tr":"şart","fa":"ضروری"},{"a":"mentor","b":"an experienced colleague who helps you","tr":"deneyimli rehber, mentor","fa":"همکار باتجربه‌ی راهنما"},{"a":"sign in","b":"write your name when you arrive","tr":"giriş kaydı yapmak","fa":"ثبت ورود"},{"a":"overtime","b":"extra hours","tr":"fazla mesai","fa":"اضافه‌کاری"},{"a":"feedback","b":"we tell you how you're doing","tr":"geri bildirim","fa":"بازخورد"},{"a":"promotion","b":"a better job later on","tr":"terfi","fa":"ترفیع"},{"a":"qualification","b":"a certificate / training in","tr":"nitelik, diploma","fa":"مدرک"}],"traps":[{"en":"Names and roles: several people are introduced. Match each one by what they do, not by the order you hear them.","tr":"İsimler ve görevler: birkaç kişi tanıtılır. Her birini duyduğun sıraya göre değil, yaptığı işe göre eşleştir.","fa":"اسم‌ها و نقش‌ها: چند نفر معرفی می‌شوند. هر کدام را با کاری که می‌کند جور کن، نه با ترتیبی که می‌شنوی."},{"en":"\"Most important\" against \"also useful\": several qualities are mentioned, but one is stressed.","tr":"\"En önemli\" ile \"bu da işe yarar\": birkaç nitelik söylenir ama biri vurgulanır.","fa":"«مهم‌ترین» در برابر «این هم مفید است»: چند ویژگی گفته می‌شود، ولی روی یکی تأکید می‌شود."},{"en":"Rules that changed: \"you used to..., but from now on...\". The answer is the new rule.","tr":"Değişen kurallar: \"eskiden..., ama artık...\". Cevap yeni kuraldır.","fa":"قانون‌هایی که عوض شده‌اند: «قبلاً...، ولی از این به بعد...». جواب قانون جدید است."}],"example":{"lines":[["Manager","Lots of people think you need a chef’s training for this job."],["Manager","You don’t. Speed comes with time, too."],["Manager","What really matters is staying calm when the kitchen gets busy."]],"item":"What does the manager say is most important?  A cooking qualifications   B staying calm under pressure   C working fast","answer":"B","why":{"en":"Training is rejected and speed \"comes with time\". \"What really matters\" stresses staying calm.","tr":"Eğitim gereksiz deniyor, hız da \"zamanla gelir\". \"What really matters\" sakin kalmayı vurguluyor.","fa":"آموزش آشپزی لازم نیست و سرعت «با زمان می‌آید». «What really matters» روی آرام ماندن تأکید می‌کند."}},"general":true,"patterns":["L2-work"],"often":{"pattern":"L2-work","n":9,"of":40,"label":{"en":"Comes up often in the real exam: 9 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Six choices, then a box of three","tr":"Altı seçim, sonra üçlü bir kutu","fa":"شش سؤال چندگزینه‌ای، بعد یک کادر سه‌تایی"},"body":{"en":"Questions 11-16: choose A, B or C. Questions 17-20: match four tasks to a box of three ideas, A-C, so at least one letter is used twice. The questions follow the order of the talk, and there is a short pause before Question 17.","tr":"Soru 11-16: A, B ya da C’yi seç. Soru 17-20: dört işi A-C arasındaki üç fikirlik bir kutuyla eşleştir; yani en az bir harf iki kez kullanılır. Sorular konuşmanın sırasını izler ve Soru 17’den önce kısa bir ara vardır.","fa":"سؤال‌های ۱۱ تا ۱۶: A، B یا C را انتخاب کن. سؤال‌های ۱۷ تا ۲۰: چهار کار را با یک کادر سه‌تایی (A تا C) جور کن، پس دست‌کم یک حرف دو بار می‌آید. سؤال‌ها به ترتیب صحبت می‌آیند و قبل از سؤال ۱۷ یک مکث کوتاه هست."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Underline the idea in the question, not in the options: \"the hardest part\", \"next project\".","tr":"Seçeneklerdeki değil, sorudaki fikrin altını çiz: \"the hardest part\", \"next project\".","fa":"زیر ایده‌ی سؤال خط بکش، نه گزینه‌ها: «the hardest part»، «next project»."},{"en":"Expect to hear all three options. Do not choose the first one you hear.","tr":"Üç seçeneğin hepsini duymayı bekle. İlk duyduğunu seçme.","fa":"انتظار داشته باش هر سه گزینه را بشنوی. اولین چیزی را که شنیدی انتخاب نکن."},{"en":"Wait for the end of the point: the answer often follows but, really, in fact or what matters most.","tr":"Noktanın sonunu bekle: cevap çoğu zaman but, really, in fact ya da what matters most’tan sonra gelir.","fa":"صبر کن تا حرف تمام شود: جواب اغلب بعد از but، really، in fact یا what matters most می‌آید."},{"en":"For the box, learn the three ideas before the pause ends, then listen for each task name.","tr":"Kutu için üç fikri ara bitmeden öğren, sonra her işin adını dinle.","fa":"برای کادر، سه ایده را قبل از تمام شدن مکث یاد بگیر، بعد منتظر اسم هر کار باش."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Mentioned is not the same as chosen","tr":"Söylenmek seçilmek demek değil","fa":"گفته شدن یعنی انتخاب شدن نیست"},"table":{"headers":{"en":["You hear","It means"],"tr":["Duyduğun","Anlamı"],"fa":["می‌شنوی","یعنی"]},"rows":[["People assume... / Everyone thinks...","a distractor follows"],["I did... but really...","the answer comes after but"],["That isn’t really why.","the option just said is wrong"],["What matters most is...","this is the answer"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One choice, step by step","tr":"Bir seçim, adım adım","fa":"یک سؤال، قدم به قدم"},"instruction":"Choose the correct letter, A, B or C.","item":"What does the speaker enjoy most about the job? A meeting famous people  B the travel  C solving problems","lines":[["Guest","You do meet a few famous faces, and that’s fun for a week. People always ask about the travel, but airports get boring. What keeps me in the job is that every day there’s a new problem to fix."]],"answer":"C","walk":[{"en":"The idea in the question: what she enjoys most.","tr":"Sorudaki fikir: en çok neden hoşlandığı.","fa":"ایده‌ی سؤال: چه چیزی را بیشتر از همه دوست دارد."},{"en":"A is only \"fun for a week\"; B is ruled out with \"but airports get boring\".","tr":"A yalnızca \"bir hafta eğlenceli\"; B \"ama havalimanları sıkıcı\" ile eleniyor.","fa":"A فقط «یک هفته جالب است»؛ B با «اما فرودگاه خسته‌کننده می‌شود» رد می‌شود."},{"en":"\"What keeps me in the job\" = what she enjoys most: C.","tr":"\"Beni bu işte tutan şey\" = en çok sevdiği şey: C.","fa":"«چیزی که مرا در این کار نگه می‌دارد» یعنی چیزی که بیشتر دوست دارد: C."}]},"quick":{"prompt":"\"Some people choose the cheapest course, but I’d say the teacher matters far more than the price.\" What does the speaker think is most important?","options":["A the price","B the length","C the teacher"],"correct":2,"why":{"en":"The price is mentioned, then \"far more than the price\" puts the teacher first.","tr":"Fiyattan söz ediliyor, sonra \"fiyattan çok daha fazla\" öğretmeni öne çıkarıyor.","fa":"از قیمت حرف می‌زند، بعد «خیلی بیشتر از قیمت» معلم را مهم‌تر می‌کند."}},"remember":{"en":"All three options are said. Choose the one that survives the but.","tr":"Üç seçenek de söylenir. \"But\"tan sonra ayakta kalanı seç.","fa":"هر سه گزینه گفته می‌شوند. گزینه‌ای را انتخاب کن که بعد از but سر جایش می‌ماند."},"type":"explain","id":"c-x01-l2-e","course":"ielts-exams","exam":"exam-01","unit":"x01-l2"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 2","title":{"en":"Backstage Careers: special-effects makeup","tr":"Backstage Careers: özel efekt makyajı","fa":"Backstage Careers: گریم جلوه‌های ویژه"},"timed":7,"ctx":["L2-work"],"script":[{"who":"Host","line":"Welcome to Backstage Careers, the podcast about the jobs you never see on screen. My guest today is Lena Ortiz, who designs special-effects makeup for theatre and television. Lena, thanks for coming in."},{"who":"Guest","line":"Thanks for having me."},{"who":"Host","line":"Let's start at the beginning. How did you get into makeup?"},{"who":"Guest","line":"People usually expect me to say I saw a famous monster film as a child. And I did watch a lot of documentaries about film studios when I was older. But it really started much earlier, when my younger brother's school put on a play and the teacher asked me to help with the makeup. I turned twenty children into old sailors, and I was hooked."},{"who":"Host","line":"And after school you went to college?"},{"who":"Guest","line":"Yes, I did a two-year course in theatre makeup. Before I started, I'd heard it was mostly theory, lectures on the history of costume and so on. In fact, there was very little of that. What made it so useful was that every term we spent two weeks working on a real production, with professional companies. Two years sounds short, but by the end I'd worked on eight shows."},{"who":"Host","line":"What was the hardest thing when you finished?"},{"who":"Guest","line":"Everyone warns you about the hours, and it's true that a theatre day can be fourteen hours long. And professional materials aren't cheap. But I'd say the real challenge is getting someone to pay you for the first time. Until you have one proper credit, nobody wants to take a risk on you."},{"who":"Host","line":"So what would you tell someone who's just starting out?"},{"who":"Guest","line":"A few things. Some people will tell you to choose a speciality straight away, but I think that's a mistake: try everything for a couple of years. Don't work for free for big companies, either; they can afford to pay. The one thing I'd insist on is that you photograph every single job you do, in good light, from the front and the side. Those pictures are what get you the next job."},{"who":"Host","line":"You work in both theatre and television. Do you have a favourite?"},{"who":"Guest","line":"Television pays better, I won't pretend it doesn't. And people assume I prefer theatre because of the live audience. I do love hearing the applause, but that isn't really why. In TV, the director usually arrives with every look already decided. In theatre, the director tends to say, 'Here's the character, show me what you'd do.' I get to design it myself, and that's what I enjoy."},{"who":"Host","line":"And what's coming up next for you?"},{"who":"Guest","line":"Well, I was offered a horror film last month, which would have been fun, but the dates didn't work. The history series I was on has just finished filming. So next month I start on a musical that's going on tour to twelve cities, which means a lot of hotel rooms."},{"who":"Host","line":"Now, I'd like to go through some of the everyday tasks of the job, and ask you what matters most for each one. Let's start with ageing an actor, making a thirty-year-old look seventy."},{"who":"Guest","line":"People think that's about being artistic, but really it's about looking very carefully. Every line has to follow the actor's real face, or it looks painted on. I spend a long time studying photographs of older people's skin before I touch a brush."},{"who":"Host","line":"What about changes between scenes, when a character comes off stage and has to look completely different?"},{"who":"Guest","line":"You might have ninety seconds. You can't stop to check every detail, and you won't have time to chat. It's simply about how fast your hands are. We practise those changes again and again until we can do them in the dark."},{"who":"Host","line":"And the first meeting with a new actor?"},{"who":"Guest","line":"That's the one people forget. Technique matters, of course, but if an actor doesn't trust you, they won't sit still for two hours while you glue things to their face. So it's about being easy to get on with: listening, being friendly, making them laugh a bit."},{"who":"Host","line":"Finally, making sure the makeup matches the costumes."},{"who":"Guest","line":"Speed isn't important there, because we test it all days before the first night. What matters is noticing tiny differences, like a lipstick that's a shade too red for the dress under the stage lights. One small mistake and the whole picture is wrong."},{"who":"Host","line":"Lena Ortiz, thank you very much."},{"who":"Guest","line":"It's been a pleasure."}],"groups":[{"instruction":"Questions 11-16. Choose the correct letter, A, B or C.","qtype":"mcq","questions":[{"n":11,"kind":"mcq","prompt":"How did Lena first become interested in makeup?","options":["A by helping with a school play","B by watching documentaries about film studios","C by seeing a famous monster film"],"correct":0,"evidence":"it really started much earlier","trap":["TR-ruledout"],"why":{"en":"The film and the documentaries came later or are what people expect. \"It really started much earlier\", at her brother’s school play.","tr":"Film ve belgeseller sonra geldi ya da insanların beklediği şey. \"Aslında çok daha önce başladı\", kardeşinin okul oyununda.","fa":"فیلم و مستندها بعدها بودند یا چیزی‌اند که مردم انتظار دارند. «در واقع خیلی زودتر شروع شد»، در نمایش مدرسه‌ی برادرش."}},{"n":12,"kind":"mcq","prompt":"What does Lena say about her college course?","options":["A It was mostly theory.","B It included time with professional companies.","C It was too short."],"correct":1,"evidence":"every term we spent two weeks working on a real production","trap":["TR-ruledout","TR-paraphrase"],"why":{"en":"\"Mostly theory\" is what she had heard; \"two years sounds short, but\". Every term she worked on a real production with professional companies.","tr":"\"Çoğunlukla teori\" duyduğu şeydi; \"iki yıl kısa gibi ama\". Her dönem profesyonel topluluklarla gerçek bir yapımda çalıştı.","fa":"«بیشتر تئوری» چیزی بود که شنیده بود؛ «دو سال کم به نظر می‌رسد، اما». هر ترم با گروه‌های حرفه‌ای روی یک اجرای واقعی کار کرد."}},{"n":13,"kind":"mcq","prompt":"According to Lena, what is the hardest thing for a new makeup artist?","options":["A the long working day","B the cost of materials","C getting the first paid job"],"correct":2,"evidence":"the real challenge is getting someone to pay you for the first time","trap":["TR-ruledout","TR-paraphrase"],"why":{"en":"Hours and materials are mentioned first. \"The real challenge is getting someone to pay you for the first time.\"","tr":"Önce saatler ve malzemeler söyleniyor. \"Asıl zorluk birinin sana ilk kez para ödemesini sağlamak.\"","fa":"اول ساعت کار و وسایل گفته می‌شوند. «چالش اصلی این است که کسی برای اولین بار به تو پول بدهد»."}},{"n":14,"kind":"mcq","prompt":"What does Lena advise new makeup artists to do?","options":["A choose a speciality as soon as possible","B take photographs of all their work","C offer to work for free for large companies"],"correct":1,"evidence":"photograph every single job you do","trap":["TR-paraphrase"],"why":{"en":"She calls specialising early \"a mistake\" and says big companies \"can afford to pay\". \"The one thing I’d insist on\": photograph every job.","tr":"Erken uzmanlaşmaya \"hata\" diyor, büyük şirketler için \"ödeyebilirler\" diyor. \"Israr edeceğim tek şey\": her işin fotoğrafını çek.","fa":"تخصص گرفتنِ زود را «اشتباه» می‌داند و می‌گوید شرکت‌های بزرگ «پولش را دارند». «تنها چیزی که رویش اصرار دارم»: از هر کار عکس بگیر."}},{"n":15,"kind":"mcq","prompt":"Why does Lena prefer working in theatre?","options":["A She enjoys the reaction of a live audience.","B She can design the makeup herself.","C The pay is better."],"correct":1,"evidence":"I get to design it myself","trap":["TR-ruledout"],"why":{"en":"TV pays better; the audience \"isn’t really why\". In theatre \"I get to design it myself\".","tr":"Televizyon daha iyi ödüyor; seyirci \"asıl neden değil\". Tiyatroda \"kendim tasarlıyorum\".","fa":"تلویزیون بیشتر پول می‌دهد؛ تماشاگر «دلیل اصلی نیست». در تئاتر «خودم طراحی‌اش می‌کنم»."}},{"n":16,"kind":"mcq","prompt":"What will Lena work on next?","options":["A a horror film","B a TV history series","C a musical on tour"],"correct":2,"evidence":"a musical that's going on tour to twelve cities","trap":["TR-ruledout"],"why":{"en":"She said no to the horror film, and the history series has finished. Next month: a touring musical.","tr":"Korku filmine hayır dedi, tarih dizisi de bitti. Gelecek ay: turneye çıkan bir müzikal.","fa":"فیلم ترسناک را رد کرد و سریال تاریخی تمام شده. ماه بعد: یک نمایش موزیکال که به تور می‌رود."}}]},{"instruction":"Questions 17-20. What does Lena say is most important for each of the following tasks? Choose the correct letter, A, B or C. NB You may use any letter more than once.","qtype":"matching","bank":["A working quickly","B paying close attention to detail","C getting on well with people"],"questions":[{"n":17,"kind":"match","prompt":"making an actor look older","correct":1,"evidence":"it's about looking very carefully","trap":["TR-paraphrase"],"why":{"en":"Not artistic talent: \"it’s about looking very carefully\" = attention to detail.","tr":"Sanatsal yetenek değil: \"çok dikkatli bakmakla ilgili\" = ayrıntıya dikkat.","fa":"نه استعداد هنری: «موضوع خیلی دقیق نگاه کردن است» یعنی دقت به جزئیات."}},{"n":18,"kind":"match","prompt":"changes between scenes","correct":0,"evidence":"how fast your hands are","trap":["TR-ruledout"],"why":{"en":"No time to check details or chat: \"it’s simply about how fast your hands are\".","tr":"Ayrıntı kontrol etmeye ya da sohbete vakit yok: \"sadece ellerinin ne kadar hızlı olduğuyla ilgili\".","fa":"وقتی برای چک کردن جزئیات یا گپ زدن نیست: «فقط به سرعت دست‌هایت بستگی دارد»."}},{"n":19,"kind":"match","prompt":"the first meeting with an actor","correct":2,"evidence":"being easy to get on with","trap":["TR-ruledout"],"why":{"en":"\"Technique matters, of course, but...\" it is about being easy to get on with.","tr":"\"Teknik önemli tabii ama...\" mesele kolay anlaşılır biri olmak.","fa":"«البته تکنیک مهم است، اما...» موضوع این است که آدم راحتی برای کنار آمدن باشی."}},{"n":20,"kind":"match","prompt":"matching the makeup to the costumes","correct":1,"evidence":"noticing tiny differences","trap":["TR-ruledout","TR-paraphrase"],"why":{"en":"\"Speed isn’t important there.\" What matters is noticing tiny differences = attention to detail.","tr":"\"Orada hız önemli değil.\" Önemli olan küçük farkları fark etmek = ayrıntıya dikkat.","fa":"«آن‌جا سرعت مهم نیست». چیزی که مهم است دیدن تفاوت‌های ریز است، یعنی دقت به جزئیات."}}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Host":{"accent":"British (Southern English)","gender":"M","tts":{"engine":"kokoro","voice":"bm_daniel"},"role":"Podcast host"},"Guest":{"accent":"North American","gender":"F","tts":{"engine":"kokoro","voice":"af_sarah"},"role":"Makeup artist (guest)"}},"sequence":[{"type":"announcer","text":"Part 2. You will hear a podcast in which a makeup artist talks about her work. First, you have some time to look at Questions 11 to 16."},{"type":"pause","seconds":30,"note":"reading time, Questions 11-16"},{"type":"announcer","text":"Now listen carefully and answer Questions 11 to 16."},{"type":"sfx","note":"short podcast jingle (2 s) under the host’s first line"},{"type":"lines","from":0,"to":13},{"type":"announcer","text":"Before you hear the rest of the podcast, you have some time to look at Questions 17 to 20."},{"type":"pause","seconds":30,"note":"reading time, Questions 17-20"},{"type":"announcer","text":"Now listen and answer Questions 17 to 20."},{"type":"lines","from":14,"to":23},{"type":"announcer","text":"That is the end of Part 2. You now have half a minute to check your answers.","after":30}]},"id":"c-x01-l2-d","course":"ielts-exams","exam":"exam-01","unit":"x01-l2"},"exit":{"type":"exit","items":[{"tests":"paraphrase","point":3,"prompt":"An option says \"the most difficult thing\". Which words in a recording mean the same?","options":["the best part was","the real challenge is","the first thing I did"],"correct":1,"why":{"en":"\"The real challenge\" = the hardest thing.","tr":"\"The real challenge\" = en zor şey.","fa":"«the real challenge» یعنی سخت‌ترین چیز."}},{"tests":"word","point":1,"prompt":"\"Until you have one proper credit, nobody takes a risk on you.\" Here, a credit is...","options":["your name listed on a professional production","a loan from a bank","a college qualification"],"correct":0,"why":{"en":"In film and theatre, a credit is your name on the list of people who worked on a production.","tr":"Film ve tiyatroda credit, bir yapımda çalışanlar listesindeki adındır.","fa":"در فیلم و تئاتر، credit یعنی اسمت در فهرست کسانی که روی یک اثر کار کرده‌اند."}},{"tests":"method","point":2,"prompt":"You hear the words of option A first. What should you do?","options":["Choose A and move on","Cross out A at once","Wait: the speaker may rule it out"],"correct":2,"why":{"en":"All three options are usually mentioned; wait for the end of the point.","tr":"Üç seçenekten de genelde söz edilir; noktanın sonunu bekle.","fa":"معمولاً هر سه گزینه گفته می‌شوند؛ صبر کن تا حرف تمام شود."}},{"tests":"trap","point":3,"prompt":"\"People think the summer is our busiest time, but it’s actually the week before the new school year.\" When is it busiest?","options":["in the summer","the week before school starts","all year"],"correct":1,"why":{"en":"\"People think...\" introduces the distractor; \"but it’s actually\" gives the answer.","tr":"\"People think...\" çeldiriciyi getirir; \"but it’s actually\" cevabı verir.","fa":"«People think...» گزینه‌ی انحرافی را می‌آورد؛ «but it’s actually» جواب را می‌دهد."}},{"tests":"method","point":1,"prompt":"In Questions 17-20 there are four tasks and only three letters. This means...","options":["at least one letter is the answer twice","one task has no answer","you must use every letter once"],"correct":0,"why":{"en":"With four questions and three letters, at least one letter is used more than once.","tr":"Dört soru ve üç harf varsa en az bir harf birden fazla kullanılır.","fa":"وقتی چهار سؤال و سه حرف هست، دست‌کم یک حرف بیش از یک بار می‌آید."}}],"id":"c-x01-l2-x","course":"ielts-exams","exam":"exam-01","unit":"x01-l2"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
